INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES 
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Um paciente de 54 anos, previamente hígido, apresenta-se à urgência com dor torácica retroesternal irradiada para o braço esquerdo há 4 horas. O eletrocardiograma (ECG) basal revela um Bloqueio de Ramo Esquerdo (BRE) sabidamente prévio. Para a correta interpretação deste ECG visando o diagnóstico de infarto agudo do miocárdio concomitante, qual conjunto de critérios deve ser aplicado e qual o achado mais específico?", "options": {"a": "Critérios de Sokolow-Lyon; presença de onda R alta em V5-V6.", "b": "Critérios de Sgarbossa; concordância do segmento ST com o complexo QRS (elevação de ST ≥ 1 mm em derivações com QRS positivo).", "c": "Critérios de Duke; infradesnivelamento de ST em DII, DIII e aVF.", "d": "Critérios de Killip; presença de B3 na ausculta.", "e": "Critérios de Cornell; amplitude de R em aVL + S em V3 > 28 mm."}, "answer": "b", "rationale": "O diagnóstico de IAM na presença de BRE prévio é um desafio. Os Critérios de Sgarbossa (ou a versão modificada de Smith) são utilizados para esse fim. O critério mais específico é a elevação de ST concordante (no mesmo sentido do QRS) ≥ 1 mm, ou o infradesnivelamento de ST concordante em V1-V3 ≥ 1 mm.", "option_rationales": {"a": "Incorreta. Sokolow-Lyon avalia hipertrofia ventricular esquerda.", "b": "Correta. Sgarbossa é o escore padrão para IAM na presença de BRE.", "c": "Incorreta. Duke é um escore para teste ergométrico ou endocardite.", "d": "Incorreta. Killip avalia insuficiência cardíaca no infarto, não o ECG.", "e": "Incorreta. Cornell avalia sobrecarga ventricular esquerda."}, "difficulty": "dificil", "tags": ["Cardiologia", "ECG", "BRE", "Sgarbossa"]}', 26, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Paciente feminina, 36 anos, no 10º dia de puerpério, sem comorbidades prévias, apresenta-se com dor torácica súbita e intensa associada a síncope. O ECG demonstra supradesnivelamento do segmento ST em parede anterior. Levada para cineangiocoronariografia, observa-se uma imagem sugestiva de um ''flap'' intimal na artéria descendente anterior, sem evidência de placas ateroscleróticas. Qual a principal suspeita diagnóstica e a conduta preferencial se a paciente estiver clinicamente estável?", "options": {"a": "Infarto tipo 1 por ruptura de placa; realizar ICP com stent imediatamente.", "b": "Dissecção Coronária Espontânea (SCAD); manejo clínico conservador inicial.", "c": "Miocardite periparto; tratamento para insuficiência cardíaca.", "d": "Tromboembolismo pulmonar com repercussão cardíaca; trombólise sistêmica.", "e": "Angina de Prinzmetal; bloqueadores de canais de cálcio e nitratos."}, "answer": "b", "rationale": "A SCAD é uma causa importante de SCA em mulheres jovens e no período periparto. Em pacientes hemodinamicamente estáveis e com fluxo coronário preservado, a conduta preferencial é o manejo clínico conservador (controle de PA, AAS e betabloqueador), pois a ICP em vasos dissecados tem alto risco de complicações (extensão da dissecção e hematoma intramural).", "option_rationales": {"a": "Incorreta. A etiologia não é aterosclerótica.", "b": "Correta. SCAD é subdiagnosticada e o puerpério é um fator de risco clássico; manejo conservador é a primeira escolha.", "c": "Incorreta. A miocardite periparto causa IC global, mas o ''flap'' na coronária confirma dissecção.", "d": "Incorreta. O ''flap'' intimal coronário é patognomônico de SCAD.", "e": "Incorreta. Prinzmetal é vasoespasmo, não dissecção física."}, "difficulty": "dificil", "tags": ["Cardiologia", "SCAD", "SCA", "Saúde da Mulher"]}', 27, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Durante uma avaliação de dor torácica no pronto-socorro, o médico observa um padrão no ECG de um paciente com dor persistente: depressão do segmento ST de 1 mm no ponto J em derivações precordiais (V1-V6) com ondas T altas, simétricas e pontiagudas, associado a uma elevação de ST em aVR. Qual o significado deste padrão eletrocardiográfico?", "options": {"a": "Padrão de repolarização precoce benigna.", "b": "Padrão de De Winter; indica oclusão aguda da artéria descendente anterior (equivalente a IAM com supra de ST).", "c": "Bloqueio intraventricular inespecífico sem valor isquêmico.", "d": "Pericardite aguda em fase inicial.", "e": "Efeito digitálico (onda em colher)."}, "answer": "b", "rationale": "O padrão de De Winter aparece em cerca de 2% das oclusões agudas da artéria descendente anterior (DA). Caracteriza-se por infra de ST no ponto J seguido de ondas T amplas e simétricas em derivações precordiais. É considerado um equivalente a IAMCSST e exige reperfusão imediata.", "option_rationales": {"a": "Incorreta. Repolarização precoce tem entalhe no ponto J e concavidade para cima, sem infra de ST.", "b": "Correta. Reconhecimento crítico de um equivalente de supra.", "c": "Incorreta. É um sinal de isquemia transmural grave.", "d": "Incorreta. Pericardite causa supra difuso e infra de PR.", "e": "Incorreta. Digital causa infra de ST côncavo, não esse padrão de T."}, "difficulty": "dificil", "tags": ["Cardiologia", "ECG", "De Winter", "Equivalente de Supra"]}', 28, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Paciente masculino, 52 anos, admitido com IAMCSST inferior há 2 horas. Apresenta-se com bradicardia intensa (FC 35 bpm) e episódios de tontura. O ECG revela Bloqueio Atrioventricular de 2º grau Mobitz I (Wenckebach). Qual a conduta inicial MAIS adequada, considerando que o paciente está sendo preparado para a sala de hemodinâmica?", "options": {"a": "Implante imediato de marcapasso transvenoso definitivo.", "b": "Atropina 0,5 mg a 1,0 mg IV e observação (frequentemente resolve bradicardias por tônus vagal no infarto inferior).", "c": "Isoproterenol em infusão contínua para manter FC > 80 bpm.", "d": "Indicar apenas compressões torácicas se houver perda de consciência.", "e": "Amiodarona venosa para evitar progressão para assistolia."}, "answer": "b", "rationale": "No infarto inferior, a bradicardia e o BAV de 2 grau (Mobitz I) costumam ser causados por hipertonia vagal (Reflexo de Bezold-Jarisch) ou isquemia transitória do nó AV (irrigado pela ACD em 90% das pessoas). Geralmente responde bem à atropina e reverte após a reperfusão coronária, raramente necessitando de marcapasso.", "option_rationales": {"a": "Incorreta. Mobitz I em infarto inferior costuma ser benigno e transitório.", "b": "Correta. Conduta conservadora e farmacológica inicial.", "c": "Incorreta. Isoproterenol aumenta o consumo de oxigênio miocárdico e pode agravar a isquemia.", "d": "Incorreta. Massagem é para parada cardíaca pura.", "e": "Incorreta. Amiodarona é bradicardizante."}, "difficulty": "media", "tags": ["Cardiologia", "Arritmias", "IAMCSST", "Atropina"]}', 29, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Sobre o uso do escore GRACE na estratificação de risco de pacientes com IAM sem supra de ST (IAMSSST), qual o objetivo principal desta ferramenta e qual o valor que define o alto risco de mortalidade hospitalar?", "options": {"a": "Avaliar o risco de sangramento; valor > 140.", "b": "Avaliar a probabilidade de oclusão total da artéria culpada; valor > 200.", "c": "Predizer a mortalidade aos 6 meses e intra-hospitalar; valor > 140 define alto risco.", "d": "Determinar se o paciente tem indicação de cirurgia de troca valvar; valor > 50.", "e": "Substituir a necessidade de dosagem de troponina; valor > 100."}, "answer": "c", "rationale": "O escore GRACE é a ferramenta de estratificação diagnóstica e prognóstica mais robusta na SCA sem supra de ST. Ele utiliza variáveis como idade, FC, PA, creatinina, classe funcional de Killip, entre outras. Um valor > 140 pontos classifica o paciente como de alto risco, indicando estratégia invasiva em até 24h.", "option_rationales": {"a": "Incorreta. Escore de sangramento seria o CRUSADE ou ARC-HBR.", "b": "Incorreta. O GRACE foca em mortalidade e reinfarto.", "c": "Correta. Definição do escore e ponto de corte para conduta invasiva precoce.", "d": "Incorreta. Finalidade absurda para o escore.", "e": "Incorreta. A troponina é uma das variáveis componentes do escore."}, "difficulty": "media", "tags": ["Cardiologia", "SCA", "GRACE", "Estratificação"]}', 30, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Paciente masculino, 60 anos, em tratamento para IAMSSST de risco intermediário. Mantém-se assintomático após início de terapia medicamentosa otimizada. Planejada cineangiocoronariografia para daqui a 48 horas. Qual estratégia de anticoagulação é PREFERENCIAL se a função renal for preservada (Creatinina 0,9 mg/dL), visando melhor balanço entre eficácia isquêmica e segurança hemorrágica?", "options": {"a": "Heparina não fracionada em infusão contínua ajustada pelo TTPA.", "b": "Fondaparinux 2,5 mg, via subcutânea, uma vez ao dia.", "c": "Enoxaparina 1 mg/kg, via subcutânea, de 12 em 12 horas.", "d": "Varfarina oral com INR alvo entre 2,0 e 3,0.", "e": "Dose única de Rivaroxabana 20 mg na admissão."}, "answer": "b", "rationale": "O estudo OASIS-5 demonstrou que, em pacientes com SCA sem supra de ST, o Fondaparinux (um inibidor seletivo do fator Xa) é superior à Enoxaparina no longo prazo devido a uma redução significativa nas taxas de sangramento maior, mantendo a eficácia isquêmica. Atualmente é a recomendação de primeira linha se o cateterismo não for imediato (classe I na diretriz europeia).", "option_rationales": {"a": "Incorreta. Requer monitorização frequente e tem maior risco de sangramento.", "b": "Correta. Preferencial pelo perfil de segurança (OASIS-5).", "c": "Incorreta. Segunda opção; eficaz, mas com mais sangramento que o fondaparinux.", "d": "Incorreta. Anticoagulação oral crônica não é indicada na fase aguda da SCA.", "e": "Incorreta. DOACs não são indicados na fase aguda isquêmica da SCA."}, "difficulty": "dificil", "tags": ["Cardiologia", "Anticoagulação", "Fondaparinux", "IAMSSST"]}', 31, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Um paciente de 45 anos, obeso e hipertenso, procura a emergência com dor precordial incaracterística de 20 minutos de duração. O primeiro ECG e a primeira troponina ultra-sensível são normais. Após 2 horas, o segundo ECG também é normal, mas a troponina apresenta uma elevação de 50% em relação ao valor basal (ainda dentro do limite superior da normalidade). De acordo com o protocolo 0/2h ou 0/3h, qual a interpretação correta?", "options": {"a": "Alta hospitalar imediata, pois a troponina está dentro da normalidade.", "b": "O paciente apresenta uma ''delta elevada'' (variação significativa), o que aumenta a suspeita de lesão miocárdica aguda e exige investigação adicional (possível SCA).", "c": "O paciente tem dor psicogênica garantida pelos exames normais.", "d": "Indicar angiotomografia de coronárias imediatamente como único exame possível.", "e": "Administrar tenecteplase para prevenir infarto iminente."}, "answer": "b", "rationale": "A utilização de troponina ultra-sensível foca não apenas no valor absoluto acima do percentil 99, mas também na variação entre as dosagens (delta). Uma variação significativa (geralmente > 20% ou valores absolutos específicos definidos pela marca do ensaio) indica processo dinâmico (lesão aguda), exigindo que o paciente seja mantido em observação/investigação.", "option_rationales": {"a": "Incorreta. A variação (delta) impede a alta.", "b": "Correta. Aplicação moderna dos protocolos com troponina ultrassensível.", "c": "Incorreta. Diagnóstico de exclusão.", "d": "Incorreta. Não é o único exame e pode ser precoce.", "e": "Incorreta. Totalmente contraindicado se não houver supra de ST."}, "difficulty": "media", "tags": ["Cardiologia", "Troponina", "Protocolo de Dor", "SCA"]}', 32, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Paciente masculino, 48 anos, tabagista, apresenta dor torácica típica e supra de ST inferior. Após trombólise bem-sucedida, o paciente mantém estabilidade hemodinâmica. A estratégia farmaco-invasiva (cineangiocoronariografia rotineira pós-trombólise) deve ser realizada em qual janela de tempo?", "options": {"a": "Imediatamente após a trombólise (dentro de 2 horas).", "b": "Entre 2 a 24 horas após do sucesso da trombólise.", "c": "Após 48 horas de estabilização.", "d": "Somente se o paciente apresentar dor novamente ou reinfarto.", "e": "Apenas antes da alta hospitalar (5º ao 7º dia)."}, "answer": "b", "rationale": "A estratégia farmaco-invasiva consiste na realização de cateterismo sistemático após sucesso na trombólise. As evidências (estudos como o GRACIA-1 e STREAM) mostram que a realização precoce (idealmente entre 2 e 24 horas) reduz a recorrência de isquemia e re-infarto em comparação com a conduta conservadora.", "option_rationales": {"a": "Incorreta. ICP imediata pós-trombólise (ICP facilitada) demonstrou pior desfecho em alguns estudos antigos. Deve-se esperar o efeito do fibrinolítico estabilizar.", "b": "Correta. Janela recomendada nas diretrizes para estratégia farmaco-invasiva.", "c": "Incorreta. Atraso excessivo perde o benefício da estabilização da placa culpada.", "d": "Incorreta. Isso seria a ''ICP de resgate'', indicada apenas se a trombólise FALHAR.", "e": "Incorreta. Tarde demais para prevenir eventos intra-hospitalares."}, "difficulty": "media", "tags": ["Cardiologia", "IAMCSST", "Farmaco-invasiva", "Trombólise"]}', 33, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Qual a principal causa de mortalidade hospitalar tardia (após a primeira semana) em pacientes que sobreviveram a um infarto agudo do miocárdio de parede anterior extenso?", "options": {"a": "Fibrilação ventricular primária.", "b": "Choque cardiogênico por falência biventricular.", "c": "Complicações mecânicas tardias e arritmias ventriculares relacionadas à cicatriz.", "d": "Infecção urinária hospitalar.", "e": "Pancreatite aguda."}, "answer": "c", "rationale": "Em sobreviventes de grandes infartos anteriores, o remodelamento ventricular pode levar a arritmias ventriculares tardias (pela cicatriz/fibrose) e complicações como aneurismas ventriculares ou insuficiência cardíaca crônica.", "option_rationales": {"a": "Incorreta. FV primária ocorre tipicamente nas primeiras 24-48 horas.", "b": "Incorreta. Choque geralmente ocorre na fase aguda.", "c": "Correta. Cicatriz e remodelamento são os principais desafios tardios.", "d": "Incorreta. Ocorre, mas não é a principal causa cardiológica.", "e": "Incorreta. Complicação rara e não característica do infarto."}, "difficulty": "moderada", "tags": ["Cardiologia", "IAM", "Prognóstico", "Remodelamento"]}', 34, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Sobre a Síndrome de Dressler, assinale a opção que descreve corretamente sua fisiopatologia, tempo de aparecimento e achado clássico ao exame físico.", "options": {"a": "Inflamação transmural direta; ocorre nas primeiras 48h; sopro sistólico.", "b": "Reação autoimune tardia contra antígenos pericárdicos/miocárdicos pós-lesão; ocorre entre 2 a 6 semanas após o infarto; atrito pericárdico e dor pleurítica.", "c": "Infecção bacteriana do pericárdio; ocorre no 5º dia; febre alta e pus na drenagem.", "d": "Embolia pulmonar pós-infarto; ocorre após 1 mês; hemoptise.", "e": "Ruptura de músculo papilar; ocorre no 3º dia; sopro holossistólico."}, "answer": "b", "rationale": "Diferente da pericardite precoce (epistenocárdica), a Síndrome de Dressler é uma condição imunomediada tardia. O paciente apresenta dor torácica que piora com a inspiração (pleurítica), melhora ao inclinar o corpo para frente (posição prece maometana), febre, leucocitose e atrito pericárdico na ausculta.", "option_rationales": {"a": "Incorreta. Isso descreve a pericardite precoce.", "b": "Correta. Definição clássica da síndrome.", "c": "Incorreta. Não é infecciosa.", "d": "Incorreta. Sem relação com Dressler.", "e": "Incorreta. Complicação mecânica, não inflamatória."}, "difficulty": "moderada", "tags": ["Cardiologia", "Dressler", "Pericardite", "IAM"]}', 35, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Paciente masculino, 65 anos, tabagista e hipertenso, procura atendimento de rotina referindo episódios de dor retroesternal em aperto, que surgem ao caminhar três quarteirões em aclive e cedem em 5 minutos após repouso. O exame físico é normal. ECG de repouso é normal. Qual o manejo inicial diagnóstico e terapêutico recomendado?", "options": {"a": "Inundar o paciente com AAS e Clopidogrel e internar na Unidade Coronariana.", "b": "Realizar teste de esforço (Teste Ergométrico) para estratificação e prescrever aspirina, estatina, betabloqueador e nitrato de curta duração para crises (manejo inicial de Angina Estável).", "c": "Encaminhar diretamente para Cirurgia de Revascularização do Miocárdio.", "d": "Prescrever apenas analgésicos e observar.", "e": "Solicitar troponina serada para excluir infarto agudo silencioso."}, "answer": "b", "rationale": "O quadro é clássico de Angina Estável ou Doença Coronária Crônica (DCC). O manejo inicial foca na estratificação de risco (testes funcionais como ergometria, cintilografia ou eco-stresse) e no tratamento farmacológico visando redução de mortalidade (AAS, estatinas) e controle de sintomas (Betabloqueadores, nitratos).", "option_rationales": {"a": "Incorreta. Paciente estável, manejo ambulatorial.", "b": "Correta. Fluxograma padrão para DCC.", "c": "Incorreta. Decisão baseada na anatomia e sintomas refratários.", "d": "Incorreta. Omissão sistemática de tratamento preventivo.", "e": "Incorreta. Troponina em quadro estável e sem dor no momento tem baixo valor."}, "difficulty": "media", "tags": ["Cardiologia", "DCC", "Angina Estável", "Manejo"]}', 36, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A cineangiocoronariografia de um paciente de 55 anos com dor torácica típica revela uma ponte miocárdica no terço médio da artéria descendente anterior, sem placas ateroscleróticas. O paciente apresenta isquemia documentada nessa parede em cintilografia de estresse. Qual a classe de medicamento que pode PIORAR os sintomas isquêmicos por induzir taquicardia reflexa ou aumentar a força de contração e compressão sistólica do vaso?", "options": {"a": "Bloqueadores de canais de cálcio não-di-hidropiridínicos (Verapamil).", "b": "Betabloqueadores (Metoprolol).", "c": "Nitratos (Isossorbida) e di-hidropiridínicos de ação curta (Nifedipina).", "d": "Estatinas.", "e": "Inibidores da ECA."}, "answer": "c", "rationale": "Na ponte miocárdica (trajeto intramural de uma coronária), a compressão do vaso ocorre durante a sístole. Medicamentos que diminuem a pré-carga ou causam taquicardia reflexa (como os nitratos e nifedipina) podem agravar o fenômeno de compressão sistólica e piorar a isquemia. O tratamento de escolha são os betabloqueadores ou bloqueadores de cálcio que reduzem a FC.", "option_rationales": {"a": "Incorreta. São úteis na ponte miocárdica.", "b": "Incorreta. São o tratamento de escolha.", "c": "Correta. Nitratos podem exacerbar a obstrução dinâmica na ponte miocárdica.", "d": "Incorreta. Neutro na ponte miocárdica.", "e": "Incorreta. Geralmente seguro, mas nitratos são os grandes vilões aqui."}, "difficulty": "dificil", "tags": ["Cardiologia", "Ponte Miocárdica", "SCA", "Terapêutica"]}', 37, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Um paciente tabagista pesado apresenta dor torácica recorrente apenas durante a madrugada. O ECG em repouso fora da dor é normal. Foi registrada uma elevação transitória do segmento ST de 4 mm em V2-V4 durante uma crise de dor às 4 da manhã, que desapareceu após 10 minutos. O médico suspeita de Angina de Prinzmetal. Qual exame é considerado o padrão-ouro para confirmação se as coronárias forem normais no cateterismo?", "options": {"a": "Holter de 24 horas.", "b": "Teste provovativo com acetilcolina ou ergonovina intracoronária durante o cateterismo.", "c": "Ecocardiograma sob estresse com dobutamina.", "d": "Ressonância magnética cardíaca com estresse por adenosina.", "e": "Teste ergométrico em rampa."}, "answer": "b", "rationale": "O diagnóstico definitivo de angina vasoespástica (Prinzmetal) requer a demonstração de espasmo coronariano focal grave que reproduz os sintomas e as alterações no ECG. Quando o evento espontâneo não é capturado, testes provocativos invasivos com substâncias vasoativas (acetilcolina ou ergonovina) são realizados com monitorização hemodinâmica e radiológica.", "option_rationales": {"a": "Incorreta. Pode capturar o evento, mas não é o padrão confirmatório se o Holter for normal.", "b": "Correta. Padrão-ouro invasivo para testes de reatividade coronária.", "c": "Incorreta. Avalia reserva contrátil, não vasoespasmo focal de tronco/epicárdio.", "d": "Incorreta. Adenosina causa vasodilatação, o oposto do necessário para testar espasmo.", "e": "Incorreta. Prinzmetal tipicamente ocorre em repouso e pode até ser inibida pelo exercício."}, "difficulty": "dificil", "tags": ["Cardiologia", "Vasoespasmo", "Prinzmetal", "Exames"]}', 38, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "No tratamento do Infarto com supra de ST, qual a dose de ataque recomendada de Aspirina (comprimidos simples para mastigar) e qual o seu principal mecanismo de ação para reduzir a mortalidade?", "options": {"a": "100 mg; reduz a inflamação do miocárdio.", "b": "162-325 mg; inibição irreversível da cicloxigenase-1 (COX-1) plaquetária, reduzindo a síntese de tromboxano A2.", "c": "500 mg; bloqueia o receptor GP IIb/IIIa.", "d": "1000 mg; inibe a via da cascata de coagulação pela protrombina.", "e": "50 mg; apenas efeito analgésico."}, "answer": "b", "rationale": "A Aspirina (AAS) é a pedra angular do tratamento da SCA. A dose de ataque deve ser de 162 a 325 mg (2 a 3 comprimidos de 100 mg), preferencialmente mastigados para absorção bucal rápida. Age inibindo precocemente a agregação plaquetária mediada pelo tromboxano.", "option_rationales": {"a": "Incorreta. 100 mg é dose de manutenção.", "b": "Correta. Dose e mecanismo clássicos.", "c": "Incorreta. GP IIb/IIIa é alvo de Tirofiban, Eptifibatide.", "d": "Incorreta. Dose muito alta e mecanismo errado.", "e": "Incorreta. Dose insuficiente."}, "difficulty": "facil", "tags": ["Cardiologia", "Farmacologia", "AAS", "SCA"]}', 39, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Qual o achado eletrocardiográfico que compõe o chamado ''Triângulo de Isquemia'' ou sinal de ''South African Flag'' (Bandeira da África do Sul) e que sugere oclusão de qual vaso?", "options": {"a": "Elevação de ST em V1, V2 e V3; indica Descendente Anterior.", "b": "Elevação de ST em DI, aVL, V2; infradesnivelamento em DIII. Indica oclusão de ramo diagonal da artéria descendente anterior.", "c": "Infradesnivelamento de ST em aVR e elevação nas demais.", "d": "Padrão RSR'' em V1 com supra de ST concavo.", "e": "Ondas U gigantes em derivações laterais."}, "answer": "b", "rationale": "O sinal da Bandeira da África do Sul (descrito graficamente pela posição das derivações no papel do ECG) envolve elevação de ST em DI, aVL, V2 e infradesnivelamento recíproco em DIII. Este padrão sugere isquemia da parede lateral alta através da oclusão de um ramo diagonal da DA ou da própria DA proximal.", "option_rationales": {"a": "Incorreta. Sugere IAM anterior típico.", "b": "Correta. Epônimo visual para oclusão de primeiro ramo diagonal (D1).", "c": "Incorreta. Isso sugere lesão de Tronco ou triarterial grave.", "d": "Incorreta. Sugere Brugada.", "e": "Incorreta. Hipocalemia ou isquemia, mas não esse sinal."}, "difficulty": "dificil", "tags": ["Cardiologia", "ECG", "Epônimos", "Diagonal"]}', 40, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Paciente masculino, 75 anos, história prévia de AVC isquêmico há 1 ano e úlcera peptídica ativa com sangramento há 2 meses. Atualmente com dor torácica típica e supra de ST de 4 mm em V1-V3. O tempo de transporte para ICP é de 4 horas. Como você avalia a indicação de trombólise?", "options": {"a": "Indicação absoluta de trombólise sistêmica imediata.", "b": "Contraindicação absoluta de trombólise; o paciente deve ser transferido para ICP mesmo que demore, ou manejo clínico conservador.", "c": "Realizar trombólise com meia-dose.", "d": "Trombólise é segura desde que se administre protetor gástrico venoso.", "e": "Indicar apenas anticoagulação oral."}, "answer": "b", "rationale": "Este paciente possui contraindicações absolutas à fibrinólise: AVC prévio (independente do tempo se for hemorrágico, ou isquêmico < 6 meses - algumas fontes estendem esse risco) e, mais criticamente, sangramento gastrointestinal ativo ou recente (último mês) e úlcera peptídica. A conduta deve ser transferência para ICP primária imediata ou, se impossível, tratamento clínico (antiagregação e heparina dependendo do risco de sangramento).", "option_rationales": {"a": "Incorreta. Alto risco de morte por sangramento.", "b": "Correta. Contraindicação absoluta é ponto fundamental no manejo de IAM.", "c": "Incorreta. Não existe meia-dose segura para contraindicação absoluta.", "d": "Incorreta. Não impede a ação sistêmica do fibrinolítico no coágulo da úlcera.", "e": "Incorreta. Anticoagulação oral não é conduta de fase aguda."}, "difficulty": "media", "tags": ["Cardiologia", "IAMCSST", "Contraindicações", "Trombólise"]}', 41, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Sobre o choque cardiogênico pós-infarto, qual parâmetro medido pelo cateter de Swan-Ganz (artéria pulmonar) define o estado de falência de bomba VE?", "options": {"a": "Pressão de oclusão da artéria pulmonar (POAP) > 18 mmHg e Índice Cardíaco (IC) < 2,2 L/min/m².", "b": "Pressão de átrio direito (PAD) < 5 mmHg e IC > 4,0.", "c": "Saturação venosa mista (SvO2) > 90%.", "d": "Resistência Vascular Sistêmica reduzida.", "e": "Pressão sistólica pulmonar < 10 mmHg."}, "answer": "a", "rationale": "O choque cardiogênico (perfil C de Forrester) é caracterizado por baixa perfusão (IC < 2,2) e sinais de congestão pulmonar (POAP > 18 mmHg). A SvO2 costuma estar baixa (< 65%) devido à maior extração tecidual periférica frente ao baixo débito.", "option_rationales": {"a": "Correta. Definição hemodinâmica clássica.", "b": "Incorreta. PAD baixa sugere hipovolemia.", "c": "Incorreta. Seria indicativa de choque distributivo/séptico ou erro de coleta.", "d": "Incorreta. No choque cardiogênico, a RVS está aumentada (compensatória).", "e": "Incorreta. Pressão pulmonar costuma estar elevada no choque cardiogênico por VE."}, "difficulty": "moderada", "tags": ["Cardiologia", "Choque", "Swan-Ganz", "Hemodinâmica"]}', 42, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Qual a duração padrão recomendada para a terapia antiagregante plaquetária dupla (DAPT) em um paciente com IAMSSST após implante de stent farmacológico de última geração, considerando que o paciente NÃO possui alto risco de sangramento?", "options": {"a": "1 mês.", "b": "3 meses.", "c": "6 meses.", "d": "12 meses.", "e": "Para o resto da vida."}, "answer": "d", "rationale": "Para pacientes que sofreram uma Síndrome Coronariana Aguda (com ou sem supra), a diretriz padrão recomenda 12 meses de DAPT (AAS + Inibidor P2Y12) para prevenir trombose de stent e novos eventos isquêmicos. Em pacientes com alto risco de sangramento, esse período pode ser encurtado (e.g., 3-6 meses).", "option_rationales": {"a": "Incorreta.", "b": "Incorreta.", "c": "Incorreta. 6 meses é o padrão para doença crônica (angina estável), não para SCA.", "d": "Correta. Intervalo padrão pós-SCA.", "e": "Incorreta. AAS é para sempre, mas o segundo agente geralmente é suspenso."}, "difficulty": "media", "tags": ["Cardiologia", "DAPT", "SCA", "Follow-up"]}', 43, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Um paciente de 40 anos, maratonista, sem fatores de risco cardiovascular, apresenta dor torácica aos grandes esforços. O ECG mostra ondas Q profundas e estreitas (ondas Q de ''septal ou de punhal'') em derivações ínfero-laterais. O ecocardiograma revela hipertrofia acentuada do septo interventricular (30 mm) e movimento sistólico anterior (SAM) da valva mitral. Qual a causa da dor torácica?", "options": {"a": "Aterosclerose coronária acelerada.", "b": "Miocardiopatia Hipertrófica (MCH); a isquemia ocorre por desbalanço oferta/demanda e compressão de pequenos vasos (small vessel disease).", "c": "Estreitamento da aorta descendente.", "d": "Valvopatia tricúspide grave.", "e": "Miocardite crônica."}, "answer": "b", "rationale": "A Miocardiopatia Hipertrófica é uma causa importante de angina em pacientes jovens. A hipertrofia maciça e o desarranjo das fibras miocárdicas levam a isquemia mesmo na ausência de doença coronariana epicárdica (tipo 2). As ondas Q em ''punhal'' no ECG são características.", "option_rationales": {"a": "Incorreta. Raro no perfil do paciente.", "b": "Correta. Diagnóstico diferencial importante de dor e alterações eletrocardiográficas.", "c": "Incorreta. Isso seria coarctação de aorta, quadro diferente.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "MCH", "Diagnóstico Diferencial", "SCA"]}', 44, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "No cenário de um IAM anterior extenso com instabilidade hemodinâmica, o Balão Intra-Aórtico (BIA) age principalmente através de qual mecanismo?", "options": {"a": "Filtragem de resíduos trombóticos da circulação.", "b": "Contrapulsação: infla na diástole (aumentando a perfusão coronária) e desinfla na sístole (reduzindo a pós-carga).", "c": "Aumenta o volume sistólico do ventrículo direito.", "d": "Substitui a função do pulmão na oxigenação do sangue.", "e": "Impede a ocorrência de embolia pulmonar."}, "answer": "b", "rationale": "O BIA é um dispositivo de assistência circulatória temporária. Ele sincroniza-se com o ciclo cardíaco: o balão infla no início da diástole (após o fechamento da valva aórtica), deslocando o sangue retrogradamente para os óstios coronários, e desinfla imediatamente antes da sístole, criando um vácuo que reduz a pós-carga e o trabalho cardíaco.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Descrição do funcionamento da contrapulsação intra-aórtica.", "c": "Incorreta.", "d": "Incorreta. Função do ECMO.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Suporte Circulatório", "BIA", "Choque"]}', 45, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A cineangiocoronariografia de urgência de um paciente com IAMCSST mostra oclusão total da Artéria Descendente Anterior (DA) e uma lesão grave (80%) na Artéria Coronariana Direita (ACD - não culpada). O paciente está estável. De acordo com os estudos COMPLETE e CVLPRIT, qual a recomendação atual sobre a lesão não culpada?", "options": {"a": "Tratar APENAS a artéria culpada (DA) e deixar o resto para tratamento clínico.", "b": "Tratar a culpada (DA) e revascularizar a lesão não culpada (ACD), preferencialmente ainda durante a internação hospitalar ou em um segundo tempo planejado.", "c": "Tratar apenas a ACD primeiro.", "d": "Encaminhar para cirurgia de revascularização triarterial urgente.", "e": "Não usar stents, apenas balão."}, "answer": "b", "rationale": "Atualmente, as diretrizes (baseadas no estudo COMPLETE) recomendam a revascularização completa de lesões não culpadas angiograficamente significativas em pacientes com IAMCSST de forma estagiada (ou até no mesmo procedimento se estável). Isso reduz a taxa de novos infartos e óbito cardiovascular em comparação a tratar apenas a lesão culpada.", "option_rationales": {"a": "Incorreta. Conduta ultrapassada para pacientes multiarticulares estáveis.", "b": "Correta. Recomendação de revascularização completa na SCA.", "c": "Incorreta. A culpada deve ser prioridade absoluta.", "d": "Incorreta. ICP é preferível se tecnicamente viável na urgência.", "e": "Incorreta."}, "difficulty": "moderada", "tags": ["Cardiologia", "Multiarterial", "IAMCSST", "Invasivo"]}', 46, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Paciente masculino, 66 anos, em uso de Nitroglicerina IV para controle de dor torácica por IAMSSST. O paciente apresenta súbita queda da saturação de oxigênio (85%) que não responde à oferta de O2 em alto fluxo, e o sangue coletado para gasometria apresenta coloração castanha (chocolate). Qual a complicação farmacológica provável?", "options": {"a": "Choque séptico por cateter central.", "b": "Metemoglobinemia induzida por nitratos.", "c": "Anemia hemolítica por AAS.", "d": "Intoxicação por Monóxido de Carbono.", "e": "Hipotensão reflexa intensa."}, "answer": "b", "rationale": "Doses elevadas ou uso prolongado de nitratos (e outros fármacos como anestésicos locais e dapsona) podem causar oxidação do ferro da hemoglobina de ferroso (Fe2+) para férrico (Fe3+), formando a metemoglobina, que não transporta oxigênio adequadamente. A coloração castanha do sangue e a cianose que não responde a O2 são sinais característicos.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Efeito adverso raro mas grave dos nitratos.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "dificil", "tags": ["Cardiologia", "Toxicologia", "Nitratos", "Efeito Colateral"]}', 47, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Qual a conduta recomendada para o tratamento de uma Síndrome Coronariana Aguda (SCA) em um paciente com Doença Renal Crônica avançada (ClCr < 15 mL/min), especificamente em relação ao uso de Enoxaparina?", "options": {"a": "Usar dose padrão de 1 mg/kg 12/12h.", "b": "A enoxaparina é contraindicada nesse nível de função renal; prefira Heparina Não Fracionada (HNF) monitorada pelo TTPA.", "c": "Usar 50% da dose de enoxaparina.", "d": "Suspender qualquer anticoagulante.", "e": "Usar Fondaparinux."}, "answer": "b", "rationale": "A enoxaparina tem excreção renal predominante. Para pacientes com ClCr < 15-30 mL/min, há alto risco de acúmulo e sangramento catastrófico. A Heparina Não Fracionada é a escolha preferencial na insuficiência renal grave, pois sua depuração é hepática/reticuloendotelial e sua monitorização por TTPA é confiável.", "option_rationales": {"a": "Incorreta. Risco altíssimo de sangramento.", "b": "Correta. Regra de segurança fundamental na nefrologia e cardiologia.", "c": "Incorreta. Mesmo 50% pode acumular perigosamente se ClCr < 15.", "d": "Incorreta.", "e": "Incorreta. Fondaparinux é contraindicado se ClCr < 20-30."}, "difficulty": "media", "tags": ["Cardiologia", "Nefrologia", "Farmacologia", "SCA"]}', 48, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Paciente masculino, 30 anos, apresenta-se com dor torácica que piora ao deitar e melhora ao sentar. O ECG mostra elevação difusa do segmento ST côncava (derivações DI, DII, aVL, V2-V6) e depressão do segmento PR em DII. Qual o tratamento farmacológico de escolha para prevenir a recorrência desta condição?", "options": {"a": "AAS + Clopidogrel.", "b": "AAS (ou Ibuprofeno) em doses inflamatórias + Colquicina.", "c": "Corticoides sistêmicos em altas doses.", "d": "Antibióticos de largo espectro.", "e": "Apenas observação."}, "answer": "b", "rationale": "O quadro é de Pericardite Aguda. O tratamento foca em AINEs (como AAS 500-1000 mg de 8/8h) para fase aguda. A adição de Colquicina (0,5 mg/dia por 3 meses) é fundamental para reduzir as taxas de recorrência da pericardite (classe I).", "option_rationales": {"a": "Incorreta. Isso trataria infarto.", "b": "Correta. Conduta baseada no estudo COPE e ICAP.", "c": "Incorreta. Corticoides são segunda linha e podem aumentar o risco de recorrência se usados como primeira linha sem necessidade (classe II).", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Pericardite", "Colquicina", "Recorrência"]}', 49, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Qual dos seguintes fármacos bloqueadores P2Y12 deve ser evitado em pacientes com história prévia de Acidente Vascular Cerebral (AVC) ou Ataque Isquêmico Transitório (AIT), pelo risco aumentado de hemorragia intracraniana?", "options": {"a": "Clopidogrel.", "b": "Prasugrel.", "c": "Ticagrelor.", "d": "Cangrelor.", "e": "Aspirina."}, "answer": "b", "rationale": "No estudo TRITON-TIMI 38, o Prasugrel demonstrou maior eficácia isquêmica que o Clopidogrel, mas à custa de mais sangramento. Em subgrupos específicos, o Prasugrel foi associado a um dano líquido (aumento de AVC hemorrágico) em pacientes com história prévia de AVC/AIT, sendo agora contraindicado formalmente para este público.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Contraindicação absoluta do Prasugrel.", "c": "Incorreta. Ticagrelor não tem essa contraindicação absoluta por AVC prévio isquêmico (apenas hemorrágico).", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Farmacologia", "SCA", "Contraindicação"]}', 50, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Um paciente de 60 anos, pós-infarto inferior há 1 mês, desenvolve dor torácica progressiva aos esforços. Cintilografia mostra isquemia em parede anterior agora. Cintilografias prévias mostravam isquemia apenas em parede inferior. Qual o termo coronariográfico para esse fenômeno em que a circulação colateral de um vaso ocluido ''rouba'' fluxo de outro território durante o esforço?", "options": {"a": "Fenômeno de No-Reflow.", "b": "Síndrome de Roubo Coronário.", "c": "Fenômeno de Raynaud.", "d": "Pseudo-isquemia.", "e": "Cascata de isquemia."}, "answer": "b", "rationale": "O ''roubo coronário'' ocorre quando a vasodilatação induzida por fármacos (ou exercício) desvia o fluxo sanguíneo de vasos colaterais isquêmicos para vasos normais vizinhos, ou de um território para outro, exacerbando a isquemia em zonas vulneráveis.", "option_rationales": {"a": "Incorreta. No-Reflow ocorre na reperfusão aguda sem fluxo microvascular.", "b": "Correta. Conceito clássico de redistribuição de fluxo isquêmico.", "c": "Incorreta. Vasospasmo de extremidades.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Hemodinâmica", "Circulação Colateral", "Fisiologia"]}', 51, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A cineangiocoronariografia de um paciente de 50 anos com dor torácica instável revela lesão ostial de artéria renal direita. Qual medicação padrão da SCA pode PIORAR subitamente a função renal desse paciente se iniciada agora?", "options": {"a": "Aspirina.", "b": "Atorvastatina.", "c": "Inibidores da ECA ou Bloqueadores de Receptores de Angiotensina.", "d": "Nitratos.", "e": "Morfina."}, "answer": "c", "rationale": "Em pacientes com estenose bilateral de artéria renal ou estenose em rim único/funcional (lesão ostial grave no caso sugerido), o bloqueio do sistema renina-angiotensina-aldosterona pode levar a uma queda aguda da taxa de filtração glomerular, pois a angiotensina II é necessária para manter a arteríola eferente contraída e garantir a pressão de filtração.", "option_rationales": {"a": "Incorreta.", "b": "Incorreta.", "c": "Correta. Contraindicação clássica em estenose de artéria renal.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Nefrologia", "iECA", "Contraindicação"]}', 52, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Paciente masculino, 55 anos, diabético, tabagista e obeso. Exames de check-up mostram LDL 130 mg/dL e HDL 35 mg/dL. Inicia quadro de angina estável aos esforços moderados. Qual o alvo de LDL recomendado para esse paciente, sendo agora classificado como de ALTO RISCO cardiovascular?", "options": {"a": "LDL < 100 mg/dL.", "b": "LDL < 70 mg/dL.", "c": "LDL < 50 mg/dL.", "d": "LDL < 30 mg/dL.", "e": "Não há alvo, apenas prescrever dieta."}, "answer": "b", "rationale": "Segundo as diretrizes brasileiras de dislipidemias, pacientes diabéticos com um ou mais fatores de risco (angina estável, tabagismo, etc) são classificados como de ALTO RISCO, com alvo de LDL < 70 mg/dL. Se fossem de muito alto risco (e.g., já tivessem sofrido infarto ou AVC), o alvo seria < 50 mg/dL.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Alvo preconizado para alto risco cardiovascular.", "c": "Incorreta. Este é o alvo para MUITO alto risco.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Dislipidemia", "Diretrizes", "Metas"]}', 53, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "A utilização de Clopidogrel para TODOS os pacientes com IAM que serão submetidos a trombólise química (estreptoquinase ou alteplase) baseia-se em qual estudo clínico?", "options": {"a": "CLARITY-TIMI 28 e COMMIT-CCS 2.", "b": "PLATO.", "c": "TRITON-TIMI 38.", "d": "SYNTAX.", "e": "VALIANT."}, "answer": "a", "rationale": "Os estudos CLARITY e COMMIT consolidaram o uso do clopidogrel (associado ao AAS e ao fibrinolítico) no IAMCSST, demonstrando redução de reinfarto e mortalidade sem aumento proibitivo de hemorragia.", "option_rationales": {"a": "Correta. Estudos marcos para o clopidogrel na fibrinólise.", "b": "Incorreta. PLATO estudou o Ticagrelor.", "c": "Incorreta. TRITON estudou o Prasugrel.", "d": "Incorreta. SYNTAX comparou ICP vs CRVM.", "e": "Incorreta. VALIANT foi sobre iECA vs BRA pós-infarto."}, "difficulty": "dificil", "tags": ["Cardiologia", "História Médica", "SCA", "Clopidogrel"]}', 54, 'draft'),
('a495682a-0c4d-44c5-bd8f-7220d7adf48f', '{"enunciado": "Qual a principal causa de choque em um paciente com IAM inferior que apresenta pulmões limpos (ausência de crepitações), turgência jugular jugular e hipotensão?", "options": {"a": "Falência grave de ventrículo esquerdo (Killip IV).", "b": "Infarto com extensão para Ventrículo Direito (VD).", "c": "Tamponamento cardíaco.", "d": "Crise de asma concomitante.", "e": "Hipotensão postural simples."}, "answer": "b", "rationale": "O infarto isolado ou extenso do Ventrículo Direito (associado à parede inferior) manifesta-se tipicamente pela tríade clínica: hipotensão, pulmões limpos e distensão venosa jugular. O VD não consegue enviar sangue para o VE, reduzindo o débito cardíaco sistêmico.", "option_rationales": {"a": "Incorreta. Falência do VE causaria edema pulmonar (estertores).", "b": "Correta. Tríade clínica clássica de infarto de VD.", "c": "Incorreta. Tamponamento também tem turgência e hipotensão, mas é mais provável ser complicação tardia se ocorrer após 3 dias; a associação com infarto INFERIOR aponta fortemente para VD.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "media", "tags": ["Cardiologia", "Infarto de VD", "Manejo", "SCA"]}', 55, 'draft');
